using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Net;
using System.Reflection;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace VinsPDF {
internal static class Updater {
 public const string Repository="DangerousKitty666/VinsPDF";
 const string Api="https://api.github.com/repos/"+Repository+"/releases/latest";
 static bool checking;
 internal sealed class UpdateInfo{public Version Version;public string Url,Hash,Name;}
 internal static UpdateInfo Parse(string json){var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);if(root.ContainsKey("draft")&&(bool)root["draft"]||root.ContainsKey("prerelease")&&(bool)root["prerelease"])throw new IOException("No stable release available.");string tag=(string)root["tag_name"];Version version;if(!Version.TryParse(tag.TrimStart('v'),out version))throw new IOException("The release version is invalid.");string expected="VinsPDF-Setup-"+tag.TrimStart('v')+".exe";foreach(Dictionary<string,object> asset in (System.Collections.IEnumerable)root["assets"]){if((string)asset["name"]!=expected)continue;string url=(string)asset["browser_download_url"],digest=asset.ContainsKey("digest")?asset["digest"] as string:null;Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="github.com"||!uri.AbsolutePath.StartsWith("/"+Repository+"/releases/download/",StringComparison.Ordinal)||!string.IsNullOrEmpty(uri.UserInfo))throw new IOException("Unexpected update location.");if(digest==null||!digest.StartsWith("sha256:")||digest.Length!=71)throw new IOException("This release is missing its SHA-256 verification digest.");return new UpdateInfo{Version=version,Url=url,Hash=digest.Substring(7),Name=expected};}throw new IOException("No Windows installer is attached to this release.");}
 internal static bool Verify(byte[] data,string expected){using(var hash=SHA256.Create())return string.Equals(BitConverter.ToString(hash.ComputeHash(data)).Replace("-",""),expected,StringComparison.OrdinalIgnoreCase);}
 sealed class Client:WebClient{protected override WebRequest GetWebRequest(Uri address){var request=base.GetWebRequest(address);request.Timeout=90000;return request;}}
 public static async void Check(Form owner){if(checking)return;checking=true;string originalTitle=owner.Text;try{ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;using(var client=new Client()){client.Headers["User-Agent"]="VinsPDF/"+Assembly.GetExecutingAssembly().GetName().Version;client.Headers["Accept"]="application/vnd.github+json";string json;try{json=await client.DownloadStringTaskAsync(Api);}catch(WebException ex){var response=ex.Response as HttpWebResponse;if(response!=null&&response.StatusCode==HttpStatusCode.NotFound){DarkMessage.Show(owner,"No published update is available yet.","VinsPDF updates");return;}throw;}var info=Parse(json);Version current=Assembly.GetExecutingAssembly().GetName().Version;var available=new Version(info.Version.Major,info.Version.Minor,Math.Max(0,info.Version.Build),Math.Max(0,info.Version.Revision));if(available<=current){DarkMessage.Show(owner,"VinsPDF is up to date ("+current.ToString(current.Build>0?3:2)+").","VinsPDF updates");return;}if(DarkMessage.Show(owner,"VinsPDF "+info.Version+" is available. Download and install it now?\nAll documents must be saved before updating.","VinsPDF updates",MessageBoxButtons.YesNo,MessageBoxIcon.Information)!=DialogResult.Yes)return;if(WindowSession.Current!=null&&!WindowSession.Current.PrepareUpdate())return;owner.Text="VinsPDF · downloading update…";byte[] data=await client.DownloadDataTaskAsync(info.Url);if(!Verify(data,info.Hash))throw new IOException("The download did not match GitHub's checksum. The update was not run.");if(WindowSession.Current!=null&&!WindowSession.Current.PrepareUpdate())return;string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"VinsPDF","Updates",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string installer=Path.Combine(folder,info.Name);File.WriteAllBytes(installer,data);string args="/SILENT /NOCLOSEAPPLICATIONS /NORESTARTAPPLICATIONS /NORESTART /WAITPID="+Process.GetCurrentProcess().Id+" /DIR=\""+AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar)+"\"";Process.Start(new ProcessStartInfo(installer,args){UseShellExecute=true});if(WindowSession.Current!=null)WindowSession.Current.CloseAll();else owner.Close();}}catch(Exception ex){if(!owner.IsDisposed)DarkMessage.Show(owner,"Could not check or install the update.\n"+ex.Message,"VinsPDF updates");}finally{checking=false;if(!owner.IsDisposed)owner.Text=originalTitle;}}
}
}
